from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = dict(jumps)
    resolved = [-1] * (n + 1)

    for start in range(n + 1):
        if resolved[start] != -1:
            continue

        path = []
        cell = start
        while resolved[cell] == -1 and cell in jump:
            path.append(cell)
            cell = jump[cell]

        if resolved[cell] == -1:
            resolved[cell] = cell

        destination = resolved[cell]
        for cell in path:
            resolved[cell] = destination

    transitions = [{} for _ in range(n + 1)]
    reverse = [[] for _ in range(n + 1)]

    for cell in range(n):
        counts = transitions[cell]
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            destination = resolved[landing]
            counts[destination] = counts.get(destination, 0) + 1

        for destination in counts:
            reverse[destination].append(cell)

    reachable = {0}
    stack = [0]
    while stack:
        cell = stack.pop()
        for destination in transitions[cell]:
            if destination not in reachable:
                reachable.add(destination)
                stack.append(destination)

    can_finish = {n}
    stack = [n]
    while stack:
        cell = stack.pop()
        for predecessor in reverse[cell]:
            if predecessor not in can_finish:
                can_finish.add(predecessor)
                stack.append(predecessor)

    # A reachable state without a path to n gives nontermination
    # positive probability. Otherwise absorption is almost sure.
    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    # Multiply E[cell] = 1 + average(E[next]) by m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for i, cell in enumerate(states):
        matrix[i][i] = m
        matrix[i][size] = m
        for destination, count in transitions[cell].items():
            if destination != n:
                matrix[i][index[destination]] -= count

    # Bareiss elimination keeps all intermediate entries integral.
    # This transient Markov-chain matrix has nonzero leading pivots.
    previous_pivot = 1
    for column in range(size - 1):
        pivot_row = matrix[column]
        pivot = pivot_row[column]

        for i in range(column + 1, size):
            row = matrix[i]
            factor = row[column]
            for j in range(column + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[column] = 0

        previous_pivot = pivot

    expectations = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectations[j]
        expectations[i] = value / matrix[i][i]

    answer = expectations[index[0]]
    return [answer.numerator, answer.denominator]
